style.css:
html, body {
  background-image: url("https://i.pinimg.com/736x/bc/db/9e/bcdb9ea040a810ab1dacccc012c26473.jpg") !important;
  background-size: cover !important;        /* makes the picture cover the whole page /
  background-position: center !important;   / centers the picture /
  background-repeat: no-repeat !important;  / doesn’t repeat the picture /
  background-attachment: fixed !important;  / picture stays in place when scrolling */
}
